    private void runPreStartGates(int index) {
        if (index >= preStartGates.size()) {
            startExtractionTask();
            return;
        }
        preStartGates.get(index).ask(ok -> {
            if (ok) {
                runPreStartGates(index + 1);
            }
        });
    }

