        host.titleEditBox().setVisible(editableTitle);
        host.titleEditBox().setManaged(editableTitle);
        host.titleInfoLabel().setVisible(showTitle && !editableTitle);
        host.titleInfoLabel().setManaged(showTitle && !editableTitle);
