            host.textPreviewArea().setText(head + text + tail);
        } else {
            host.textPreviewArea().setText(head
                    + text.substring(0, 5000)
                    + Texts.get("preview.extractedContentDivider")
                    + text.substring(text.length() - 5000)
                    + tail);
        }
    }

